contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test entry. We try sending with arbitrary receiver and amount.
    function run(address receiver, uint amount) public payable {
        require(true);

        // Attempt the call and record whether it reverted.
        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // If the call did not revert, then it must have satisfied the function's require-conditions:
        // caller == owner (the deployer of c) and receiver != address(0) and amount > 0.
        // In this test environment, calls to c are made with msg.sender == address(this) (the InvMutTest contract),
        // and c's owner is set to its constructor sender (which is also address(this) when c was deployed by the test harness).
        // We cannot directly read owner (it's not public), but we can reason that only the deployer/owner may succeed.
        // So we assert: if not reverted then receiver != 0 and amount > 0.
        // Additionally, because any non-owner call must revert, and this test contract was the deployer/owner of c,
        // a successful call implies the caller was indeed the owner (address(this)).

        assert(reverted || (receiver != address(0) && amount > 0));
    }

    receive() external payable {}
}

